  'teach.up.help_columns': { ko: '다른 이름도 됩니다: 질문은 question / q / 질문, 정답은 completion / output / a / 정답, 다른 표현은 alt / paraphrase / 다른표현.', en: 'Other names work too: "question" / "q" / "질문" for the question, "completion" / "output" / "a" / "정답" for the answer, "alt" / "paraphrase" / "다른표현" for another way to ask.' },
  'teach.up.sample': { ko: '예시 데이터셋 내려받기', en: 'Download a sample dataset' },
  'teach.up.sample_hint': { ko: '질문 몇 개짜리 jsonl — 열어서 내용만 바꿔 다시 올리세요.', en: 'A handful of questions in jsonl — open it, replace the text with yours, upload it back.' },
  'teach.up.sample_use': { ko: '이 예시로 시작하기', en: 'Start from this sample' },
  'teach.up.sample_rows': { ko: '질문 {n}개', en: '{n} questions' },
  // SC-9 — the visitor arrived from a knowledge page with `?on=`: they may copy its questions, or bring their own file.
  'teach.up.on_own': { ko: '아니면 내 질문 파일을 올리세요 — 그 지식 위에 얹어서 학습합니다.', en: 'Or bring your own questions below — they are taught on top of it.' },
  'teach.up.privacy': { ko: '학습하는 동안 파일이 이 노드에 저장되고 노드 운영자가 볼 수 있습니다. 개인정보나 공유할 수 없는 내용은 올리지 마세요.', en: 'Your file is stored on this node while it trains, and the node operator can see it. Do not upload personal data or anything you are not allowed to share.' },
  'teach.up.next': { ko: '이 질문들 확인하기', en: 'Check these questions' },
  'teach.up.encoding': { ko: '{encoding}(으)로 읽었습니다. 글자가 깨져 보이면 UTF-8로 저장해 다시 올리세요.', en: 'Read as {encoding}. If the text looks wrong, save the file as UTF-8 and upload it again.' },
  'teach.up.key_made': { ko: '이 브라우저의 가르치기 키로 데이터셋에 서명했습니다 ({short}). 키를 잃으면 데이터셋과 수업에 다시 접근할 수 없습니다 — 백업해 두세요.', en: 'Your dataset was signed with this browser\'s teaching key ({short}). Lose the key and you lose access to your datasets and lessons — back it up.' },
  'teach.up.key_backup': { ko: '키 백업하기', en: 'Back up the key' },
  'teach.up.err_empty': { ko: '이 파일에서 질문·정답 쌍을 찾지 못했습니다. 아래 형식 예시를 확인하세요.', en: 'No question and answer pairs were found in that file. Check the format examples below.' },
  'teach.up.err_big': { ko: '파일이 {size}로 {mb} MB 제한을 넘습니다. 파일을 나누거나 질문 수를 줄이세요.', en: 'That file is {size}, over the {mb} MB limit. Split it, or upload fewer questions.' },
  'teach.up.err_type': { ko: '이 노드는 jsonl, csv, tsv, 일반 텍스트를 읽습니다. "{name}"은(는) 해당하지 않습니다.', en: 'This node reads jsonl, csv, tsv and plain text. "{name}" is none of those.' },
  // item 15 — the extension said .csv and the bytes said otherwise; nothing is uploaded and no quota is spent
  'teach.up.err_binary': { ko: '"{name}"은(는) 글자가 아니라 이진 파일로 보입니다. 엑셀/시트라면 CSV로 내보낸 뒤 그 파일을 올려주세요.', en: '"{name}" looks like a binary file, not text. If it is a spreadsheet, export it as CSV and upload that file instead.' },
  'teach.up.err_read': { ko: '파일을 읽지 못했습니다. UTF-8 텍스트로 다시 저장해 보세요.', en: 'That file could not be read. Try saving it again as UTF-8 text.' },
  'teach.up.err_many': { ko: '파일에 질문이 {n}개 있습니다. 이 노드는 한 데이터셋에 {max}개까지 받습니다. 앞의 {max}개만 불러왔습니다.', en: 'That file has {n} questions; this node accepts up to {max} in one dataset. The first {max} were loaded.' },

