  'teach.res.publish_body': { ko: '이 노드를 통해 마켓에 올라가고 내 이름으로 남으며, 판매마다 {share}%를 받습니다.', en: 'It goes on the marketplace through this node, credited to you, and you receive {share}% of every sale.' },
